"use client";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  MessageSquare,
  Clock,
  User,
  Calendar,
  MapPin,
  AlertCircle,
} from "lucide-react";

const getStatusColor = (status: string) => {
  switch (status) {
    case "Pending":
      return "bg-yellow-100 text-yellow-800";
    case "In Progress":
      return "bg-blue-100 text-blue-800";
    case "Resolved":
      return "bg-green-100 text-green-800";
    case "Rejected":
      return "bg-red-100 text-red-800";
    default:
      return "bg-gray-100 text-gray-800";
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case "High":
      return "bg-red-100 text-red-800";
    case "Medium":
      return "bg-yellow-100 text-yellow-800";
    case "Low":
      return "bg-green-100 text-green-800";
    default:
      return "bg-gray-100 text-gray-800";
  }
};

interface ComplaintModalProps {
  complaint: any;
  onClose: () => void;
}

export function ComplaintModal({ complaint, onClose }: ComplaintModalProps) {
  const updates = [
    {
      date: "2024-08-07 10:30 AM",
      status: "Complaint Submitted",
      message:
        "Your complaint has been received and assigned ID: " + complaint.id,
      user: "System",
    },
    {
      date: "2024-08-07 2:15 PM",
      status: "Under Review",
      message: "Complaint is being reviewed by the maintenance team.",
      user: "Admin",
    },
    {
      date: "2024-08-08 9:00 AM",
      status: "In Progress",
      message: "Maintenance team has been assigned to resolve the issue.",
      user: "Maintenance Team",
    },
  ];

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageSquare className="w-5 h-5" />
            Complaint Details
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-semibold">{complaint.title}</h3>
            <div className="flex gap-2">
              <Badge className={getStatusColor(complaint.status)}>
                {complaint.status}
              </Badge>
              <Badge className={getPriorityColor(complaint.priority)}>
                {complaint.priority} Priority
              </Badge>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-gray-600">
                  Complaint ID
                </label>
                <p className="mt-1 font-mono">{complaint.id}</p>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Category
                </label>
                <p className="mt-1">{complaint.category}</p>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Date Submitted
                </label>
                <div className="flex items-center gap-2 mt-1">
                  <Calendar className="w-4 h-4 text-gray-400" />
                  <span>{complaint.date}</span>
                </div>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Location
                </label>
                <div className="flex items-center gap-2 mt-1">
                  <MapPin className="w-4 h-4 text-gray-400" />
                  <span>Flat 204, Building A</span>
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-gray-600">
                  Priority Level
                </label>
                <div className="flex items-center gap-2 mt-1">
                  <AlertCircle className="w-4 h-4 text-gray-400" />
                  <span>{complaint.priority}</span>
                </div>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Assigned To
                </label>
                <div className="flex items-center gap-2 mt-1">
                  <User className="w-4 h-4 text-gray-400" />
                  <span>Maintenance Team</span>
                </div>
              </div>

              <div>
                <label className="text-sm font-medium text-gray-600">
                  Expected Resolution
                </label>
                <div className="flex items-center gap-2 mt-1">
                  <Clock className="w-4 h-4 text-gray-400" />
                  <span>2-3 business days</span>
                </div>
              </div>
            </div>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-600">
              Description
            </label>
            <p className="mt-2 p-4 bg-gray-50 rounded-lg">
              {complaint.description}
            </p>
          </div>

          <div>
            <h4 className="font-medium mb-4">Status Updates</h4>
            <div className="space-y-4">
              {updates.map((update, index) => (
                <Card key={index}>
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="font-medium text-sm">
                            {update.status}
                          </span>
                          <span className="text-xs text-gray-500">
                            by {update.user}
                          </span>
                        </div>
                        <p className="text-sm text-gray-700">
                          {update.message}
                        </p>
                      </div>
                      <span className="text-xs text-gray-500">
                        {update.date}
                      </span>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>

          <div className="flex gap-3 pt-4 border-t">
            <Button className="flex-1">Contact Support</Button>
            <Button variant="outline">Download Report</Button>
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
